program.command("hook-dispatch <event>").description("Unified hook dispatcher \u2014 handles all teamai hooks for a given event in one process").option("--stdin", "Read hook data from STDIN (accepted for forward compat, always reads STDIN)").option("--tool <name>", "Tool identifier (e.g. codebuddy, workbuddy, claude)").option("--matcher <matcher>", "Hook matcher for PostToolUse (e.g. Skill, Bash)").option("--bg-only", "Internal: run only fire-and-forget background handlers (used by the detached child)").action(async (event, cmdOpts) => {
  const bgOnly = cmdOpts.bgOnly ?? false;
  const HOOK_HARD_EXIT_MS = 7e3;
  let hardExit;
  if (!bgOnly) {
    hardExit = setTimeout(() => process.exit(0), HOOK_HARD_EXIT_MS);
    hardExit.unref();
  }
  const { hookDispatchCli: hookDispatchCli2 } = await Promise.resolve().then(() => (init_hook_dispatch_cli(), hook_dispatch_cli_exports));
  try {
    await hookDispatchCli2(event, cmdOpts.tool ?? "claude", cmdOpts.matcher ?? "*", bgOnly);
  } finally {
    if (hardExit) clearTimeout(hardExit);
    process.exit(0);
  }
});
